import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);

  const trimmed = email.trim();
  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
  const errorText = touched && trimmed.length > 0 && !isValid
    ? 'Укажите адрес вида name@example.com'
    : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${trimmed}`,
      variant: 'success',
    });
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '420px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        helperText="Раз в неделю, без спама"
        errorText={errorText}
      />

      <div style={{ display: 'flex', gap: '8px' }}>
        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Подписаться
        </JxButton>
      </div>

      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="top-right"
      />
    </form>
  );
}

